package dev.nihit.gitdash.output;
import com.fasterxml.jackson.databind.ObjectMapper;import dev.nihit.gitdash.model.*;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.file.Path;import java.time.Instant;import java.util.List;import static org.assertj.core.api.Assertions.assertThat;
class RenderersTest{private RepositoryStatus status(){return new RepositoryStatus(new Repository("repo",Path.of("/tmp/repo"),Instant.EPOCH),RepositoryState.DIRTY,"main",false,1,0,2,0,0,0,"origin/main",1,2,"origin","https://example/x","abc","abc","subject",Instant.EPOCH,"Author",true,null);}@Test void jsonIsValidAndVersioned()throws Exception{var w=new StringWriter();Renderers.json(List.of(status()),new PrintWriter(w));var root=new ObjectMapper().readTree(w.toString());assertThat(root.get("schemaVersion").asInt()).isEqualTo(1);assertThat(root.get("repositories").get(0).get("name").asText()).isEqualTo("repo");}@Test void porcelainIsTabSeparatedAndStable(){var w=new StringWriter();Renderers.porcelain(List.of(status()),new PrintWriter(w));assertThat(w.toString()).isEqualTo("/tmp/repo\tmain\tdirty\t1\t2\torigin/main\n");}}
